-- The @username is the person's reference and the name shown when they set
-- no nickname (owner decision, 2026-11-21): it must be chosen by the person,
-- never derived from the email. username_chosen records that it was: true
-- from registration (now required) or once the person changes or confirms it.
-- Usernames generated by ryze_users_default_username() (Google sign-up,
-- accounts made before 000049, accounts created by administrators) stay false
-- and the person is asked to choose one on their next visit.
ALTER TABLE users ADD COLUMN username_chosen BOOLEAN NOT NULL DEFAULT false;
